-- Production column lists (pg_attribute, 2026-09-28) of every table the union
-- P&L evidence path reads, with the indexes production already has.
CREATE TABLE public.cash_funding_application_receipts (pending_addon_id uuid PRIMARY KEY, funding_receipt_id uuid UNIQUE, applied_at timestamp with time zone, original_occupancy_id uuid, applied_occupancy_id uuid, applied numeric, refunded numeric, transaction_id xid8);
CREATE TABLE public.cash_hand_provenance_receipts (table_id uuid, hand_number bigint, hand_id uuid UNIQUE, accepted_at timestamp with time zone, payload_hash text, accepted_request jsonb, manifest_id uuid, atomic_receipt jsonb, stack_claim jsonb, stack_settlement jsonb, version integer, status text, game_scope jsonb, participants jsonb, signed_external_net numeric, rake numeric, bbj numeric, all_players_included boolean, funding_provenance_complete boolean, issues jsonb, transaction_id xid8, PRIMARY KEY(table_id,hand_number));
CREATE INDEX cash_hand_provenance_time ON public.cash_hand_provenance_receipts USING btree (accepted_at, table_id, hand_number);
CREATE TABLE public.cash_participant_funding_receipts (id uuid PRIMARY KEY, recorded_at timestamp with time zone, operation_kind text, operation_key text, user_id uuid, table_id uuid, seat_id uuid, occupancy_id uuid, seat_joined_at timestamp with time zone, source_ledger_id uuid UNIQUE, wallet_transaction_id uuid, account_type text, account_entity_id uuid, funding_club_id uuid, funding_union_id uuid, asset text, unit_scale integer, amount numeric, balance_before numeric, balance_after numeric, pending_addon_id uuid UNIQUE, transaction_id xid8, UNIQUE(operation_kind, operation_key));
CREATE INDEX cash_participant_funding_occupancy ON public.cash_participant_funding_receipts USING btree (occupancy_id, recorded_at, id);
CREATE TABLE public.tournament_accounting_credit_receipts (transaction_id xid8, id uuid PRIMARY KEY, observed_at timestamp with time zone, idempotency_key text UNIQUE, tournament_id uuid, user_id uuid, asset text, amount numeric, ledger_id uuid UNIQUE, wallet_transaction_id uuid UNIQUE, payout_id uuid UNIQUE, credited_club_id uuid, ledger_snapshot jsonb, wallet_snapshot jsonb, payout_snapshot jsonb, registration_snapshot jsonb, tournament_snapshot jsonb, entry_receipt_ids uuid[]);
CREATE TABLE public.tournament_participant_funding_receipts (id uuid PRIMARY KEY, transaction_id xid8, observed_at timestamp with time zone, registration_id uuid, tournament_id uuid, user_id uuid, operation text, purchase_key text, asset text, amount numeric, entitlement_id uuid UNIQUE, ledger_id uuid UNIQUE, wallet_transaction_id uuid UNIQUE, funding_club_id uuid, registration_snapshot jsonb, tournament_snapshot jsonb, entitlement_snapshot jsonb, ledger_snapshot jsonb, wallet_snapshot jsonb, custody_result jsonb);
CREATE INDEX tournament_participant_fundin_tournament_id_registration_id_idx ON public.tournament_participant_funding_receipts USING btree (tournament_id, registration_id, observed_at);
CREATE TABLE public.tournament_refund_tranches (wallet_transaction_id uuid, idempotency_key text, tournament_id uuid, obligation_id uuid, user_id uuid, source_wallet_club_id uuid, entitlement_id uuid, credit_ledger_id uuid, amount_paid_before numeric(15,2), amount_paid_now numeric(15,2), refund_prize numeric(15,2), refund_bounty numeric(15,2), refund_fee numeric(15,2), source text, description text, created_at timestamp with time zone, transaction_id xid8);
CREATE TABLE public.union_pnl_cash_outcome_resolutions (table_id uuid, hand_number bigint, hand_id uuid UNIQUE, outcome_payload_hash text, outcome_evidence_md5 text, resolution_kind text, proof jsonb, reason text, resolved_by text, resolved_at timestamp with time zone, PRIMARY KEY(table_id,hand_number));
CREATE TABLE public.union_pnl_cash_outcomes (table_id uuid, hand_number bigint, hand_id uuid UNIQUE, transaction_id xid8, recognized_at timestamp with time zone, payload_hash text, game_scope jsonb, evidence jsonb, PRIMARY KEY(table_id,hand_number));
CREATE INDEX union_pnl_cash_outcomes_expr_recognized_at_idx ON public.union_pnl_cash_outcomes USING btree (((game_scope ->> 'game_union_id'::text)), recognized_at);
CREATE TABLE public.union_pnl_inventory_capture (singleton boolean PRIMARY KEY, captured_at timestamp with time zone, contract_version integer, source_counts jsonb);
CREATE TABLE public.union_pnl_inventory_events (event_id bigint PRIMARY KEY, source_name text, row_id uuid, observed_at timestamp with time zone, transaction_id xid8, operation text, before_row jsonb, after_row jsonb);
CREATE INDEX union_pnl_inventory_identity ON public.union_pnl_inventory_events USING btree (source_name, row_id, event_id DESC);
CREATE INDEX union_pnl_inventory_boundary ON public.union_pnl_inventory_events USING btree (observed_at, event_id);
CREATE INDEX union_pnl_inventory_transaction ON public.union_pnl_inventory_events USING btree (transaction_id, source_name);
CREATE TABLE public.union_pnl_original_flows (ledger_id uuid PRIMARY KEY, transaction_id xid8, recognized_at timestamp with time zone, game_scope jsonb, ledger_snapshot jsonb);
CREATE INDEX union_pnl_original_flows_expr_recognized_at_idx ON public.union_pnl_original_flows USING btree (((game_scope ->> 'game_union_id'::text)), recognized_at);
CREATE TABLE public.union_pnl_transaction_frames (transaction_id xid8 PRIMARY KEY, observed_at timestamp with time zone, book_start timestamp with time zone);
CREATE TABLE public.union_pnl_weekly_capture (singleton boolean PRIMARY KEY, captured_at timestamp with time zone, contract_version integer);
-- accounting_payable_earning_sources is a view in production; the report reads
-- only these columns of it.
CREATE TABLE public.accounting_payable_earning_sources (source_type text, club_id uuid, union_id uuid, earned_at timestamptz, rake_credit numeric);
